find_invoices.beforeRequest:
const filters = [inputs.invoiceNumber ? 'InvoiceNumber="' + inputs.invoiceNumber + '"' : '', inputs.supplier ? 'Supplier="' + inputs.supplier + '"' : '', inputs.businessUnit ? 'BusinessUnit="' + inputs.businessUnit + '"' : '', inputs.validationStatus ? 'ValidationStatus="' + inputs.validationStatus + '"' : ''].filter(Boolean);
const query = { limit: Math.min(Number(inputs.limit) || 25, 500), offset: Number(inputs.offset) || 0 };
if (filters.length) query.q = filters.join(' AND ');
const form = value => encodeURIComponent(value).replace(/[!'()~]/g, c => '%' + c.charCodeAt(0).toString(16).toUpperCase()).replace(/%20/g, '+');
request.url += '?' + Object.keys(query).map(key => key + '=' + form(query[key])).join('&');
return request;

